  char cVar2;
  int iVar3;
  ulonglong uVar4;
  longlong *plVar5;
  ulonglong uVar6;
  ulonglong uVar7;
  
                    /* Never mutate the entry array during recursive broadcast execution. */
                    /* Registration uses amortized thresholding; post-broadcast cleanup passes false
                       for immediate compaction. */
  if ((pCollection->nRecursionDepth < 1) &&
     ((!fUseCompactionThreshold ||
      (pCollection->nCompactionThreshold = pCollection->nCompactionThreshold + -1,
      pCollection->nCompactionThreshold <= pCollection->nCount)))) {
    iVar1 = pCollection->nCount;
    uVar6 = 0;
    uVar7 = uVar6;
    if (0 < iVar1) {
      do {
                    /* Select the current FCallbackEntry_Partial from inline storage or
                       pHeapEntries. */
        uVar4 = ((ulonglong)(pCollection->pHeapEntries != (FCallbackEntry_Partial *)0x0) - 1 &
                 (ulonglong)pCollection | (ulonglong)pCollection->pHeapEntries) + uVar6;
                    /* Select the callback object from the entry's inline prefix or +0x20 heap
                       pointer. */
                    /* Typed virtual +0x30 reports whether the weak callback may be compacted. */
        if (((*(int *)(uVar4 + 0x30) == 0) ||
            (plVar5 = (longlong *)
                      ((ulonglong)(*(longlong *)(uVar4 + 0x20) != 0) - 1 & uVar4 |
                      *(ulonglong *)(uVar4 + 0x20)), plVar5 == (longlong *)0x0)) ||
           (cVar2 = (**(code **)(*plVar5 + 0x30))(), cVar2 != '\0')) {
          SmallArray_DestroyRange_Stride64(pCollection,uVar7,1,1);
        }
        else {
          uVar7 = (ulonglong)((int)uVar7 + 1);
          uVar6 = uVar6 + 0x40;
        }
      } while ((int)uVar7 < pCollection->nCount);
    }
                    /* Re-arm the threshold from the surviving count and shrink excess capacity when
                       useful. */
    iVar3 = pCollection->nCount * 2;
    if (iVar3 < 3) {
      iVar3 = 2;
    }
    pCollection->nCompactionThreshold = iVar3;
